	regionKind = "place",
	kind = "region",
	sections = {
		{
			title = "Summary",
			text = [=[North-east of {link:booty-bay}Booty Bay{/link}, on the Crystal Shore, stand two ruined troll towns: Aboraz and Jubuwal. They are the realm of {link:zanzil-the-outcast}Zanzil the Outcast{/link}, a witch doctor cast out by his own tribe. His followers live on his mixture and do not question him. The dead walk here too. Three gamblers of Booty Bay who could not pay their debts now wander these ruins, cursed and bewitched. Among Zanzil's thralls was once a young {link:darkspear-trolls}Darkspear{/link}, the lost son of a chief.]=],
		},
	},
})

