Add({
	kind = "figure",
	id = "baron-revilgaz",
	title = "Baron Revilgaz",
	aliases = { "Revilgaz" },
	subtitle = "Lord of Booty Bay",
	tier = "B",
	region = "stranglethorn-vale",
	npc = { 2496 },
	allegiance = "Booty Bay · Steamwheedle Cartel",
	found = "Booty Bay, the top floor of the tavern across the harbor",
