			hint = [=[Bring the Baron word of the haunted isle, and follow where it leads.]=],
			unlock = {
				{ type = "quest", id = 611 },
			},
			text = [=[Sailors in the tavern spoke of an island off the coast, haunted by water elementals and a raving goblin ghost. {link:krazek}Krazek{/link} passed the tale on, and Revilgaz remembered a troll legend he had once read: the Stone of the Tides, a relic that curses its bearer to fade in and out of the world. A goblin wizard named Gazban was said to have found it. Revilgaz would not leave {link:booty-bay}Booty Bay{/link} to talk with tiresome mages himself, so he sent the bracers of the elementals to {link:dalaran}Dalaran{/link}. {link:archmage-ansirem-runeweaver}Ansirem{/link} found the trace of the curse, and a troll dagger to break it. The Stone now has a place of honor in {link:the-baron}the Baron{/link}'s collection.]=],
		},
		{
