			title = "A Sponsor's Favor",
			hint = [=[Seek the Baron's help on behalf of a goblin racer of the Shimmering Flats.]=],
			unlock = {
				{ type = "quest", id = 1182 },
			},
			text = [=[The goblin racer {link:pozzik}Pozzik{/link} had been promised a new fuel regulator from {link:booty-bay}Booty Bay{/link}, and it never came. The {link:venture-company}Venture Company{/link}'s shredders at {link:lake-nazferiti}Lake Nazferiti{/link} used the new design, and their foreman kept its blueprints under lock and key. Revilgaz wanted them copied, for Pozzik's sake and for his own notes. He does not like his racers to think their sponsors have abandoned them.]=],
