	pin = { x = 35.7, y = 10.8 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Find the dwarven hunter whose camp stands upriver of Lake Nazferiti.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Hemet Nesingwary is a {link:dwarves}dwarf{/link}, a hunter and a teller of hunting tales. His companions call him a renowned hero of the {link:alliance}Alliance{/link}, and he fought on the battlefields of {link:lordaeron}Lordaeron{/link} before he took up the rifle for sport. He has hunted across the world. Now he has come to {link:stranglethorn-vale}Stranglethorn{/link} with a band of fellow hunters, and one beast above all has drawn him here: the white tiger {link:king-bangalash}King Bangalash{/link}.]=],
		},
		{
			title = "Significance",
			text = [=[Nesingwary is famous, rich and well connected. Even the goblins of {link:booty-bay}Booty Bay{/link} take care to learn what he is doing. He is proud of his skill and generous to anyone who can match it, whatever their race or banner. He has written the tale of his hunts in the jungle, and his companions hope to see it read throughout the world.]=],
		},
		{
			title = "Deeds",
			text = [=[• He set up his camp by the northern river with {link:barnil-stonepot}Barnil Stonepot{/link}, {link:ajeck-rouack}Ajeck Rouack{/link} and {link:sir-s-j-erlgadin}Sir S. J. Erlgadin{/link}.
• He tests newcomers in the hunting of raptors, while Ajeck judges them against tigers and Sir Erlgadin against panthers.
• He hunted the beasts of {link:desolace}Desolace{/link} with the {link:tauren}tauren{/link} {red:roon-wildmane}Roon Wildmane{/red}, and the two became friends despite the old enmity of their peoples.
• He ordered a crate of special ammunition from a goblin of the {link:the-shimmering-flats}Shimmering Flats{/link} before he left for the jungle.
• He wrote {i}{link:green-hills-of-stranglethorn}Green Hills of Stranglethorn{/link}{/i}, the story of his hunts.]=],
		},
	},
	chapters = {
		{
