			hint = "Bring the hunter a gift from a friend far away.",
			unlock = {
				{ type = "quest", id = 5762 },
				{ type = "quest", id = 5763 },
			},
			text = [=[Gifts still find their way to the camp across the sea. A goblin merchant of the {link:the-shimmering-flats}Shimmering Flats{/link} sent on a crate of ammunition that Hemet had paid for long before. A {link:tauren}tauren{/link} of {link:desolace}Desolace{/link} sent a kodo horn, and with it an invitation to hunt together once more. Hemet was glad of both. He is deep in the jungle for now, but he has not forgotten the land of the centaurs.]=],
