Add({
	kind = "figure",
	id = "lieutenant-doren",
	title = "Lieutenant Doren",
	aliases = { "Doren" },
	subtitle = "Leader of the Rebels",
	tier = "B",
	region = "stranglethorn-vale",
	npc = { 469 },
	allegiance = "Kingdom of Stormwind · Rebel Camp",
	found = "The Rebel Camp, in the far north of the jungle",
	pin = { x = 38.0, y = 3.0 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Seek the officer who leads the rebels near the road from Duskwood.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Lieutenant Doren commands the rebels of {link:stranglethorn-vale}Stranglethorn{/link}. He and his soldiers once served {link:colonel-kurzen}Colonel Kurzen{/link}, and they were fiercely loyal to him. Then the colonel changed. As Kurzen sank into cruelty, his men's devotion turned to rage, and Doren led those who would not follow him any longer into a camp of their own. They have been at war with their old commander ever since.]=],
		},
		{
			title = "Significance",
			text = [=[Doren fights a war he cannot win alone. {link:colonel-kurzen}Kurzen{/link} is a brilliant tactician, and his men outnumber the rebels many times over. The rebels survive on goblin supplies, on stolen medicine and on secrets. Doren must guard those secrets well, for a single word in the wrong ear could put a knife to his soldiers' throats.]=],
		},
		{
			title = "Deeds",
			text = [=[• He holds the {link:rebel-camp}Rebel Camp{/link} against the colonel's forces.
• He sent {link:private-thorsen}Private Thorsen{/link} back among {link:colonel-kurzen}Kurzen{/link}'s men as a spy.
• He sought the records of Bookie {link:herod}Herod{/link}, Kurzen's keeper of stores, to learn how Thorsen's secret was betrayed.
• He found the traitor in his own camp.
• He sent a champion into the Stockpile to face the colonel himself.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No record tells how Doren's company came to serve in {link:stranglethorn-vale}Stranglethorn{/link}, or when the rebels broke from their colonel.]=],
		},
	},
	chapters = {
		{
			key = "the-traitor-in-the-camp",
			title = "The Traitor in the Camp",
			hint = "Help the lieutenant learn who betrayed his spy.",
			unlock = {
				{ type = "quest", id = 331 },
			},
			text = [=[Only three people knew of {link:private-thorsen}Thorsen{/link}'s mission: Doren, {link:sergeant-yohwa}Sergeant Yohwa{/link} and Thorsen himself. Yet {link:colonel-kurzen}Kurzen{/link}'s men had known it too. In Bookie {link:herod}Herod{/link}'s strongbox lay a muddy note that listed Thorsen's patrols, his friends and his habits, signed with a single letter. The patrol schedules told the rest. The man who had shared Thorsen's watch all that week was Private Merle. Doren had thought him a brave soldier with a true heart. The discovery pained him, and it relieved him more.]=],
		},
		{
			key = "the-fall-of-the-colonel",
			title = "The Fall of the Colonel",
			hint = "Carry the rebels' hope into the Stockpile.",
			unlock = {
				{ type = "quest", id = 202 },
			},
			text = [=[When the colonel's jungle fighters were thinned and his special forces broken, Doren asked for the last and hardest deed. The one who had fought for the rebels was to enter the Stockpile, pass {link:colonel-kurzen}Kurzen{/link}'s defenders, and face the colonel and his captains. Doren could hardly believe the report when it came. For the first time since the rebellion began, his soldiers could breathe easier.]=],
		},
	},
