	npc = { 2497 },
	allegiance = "Darkspear Trolls · Horde",
	found = "Grom'gol Base Camp",
	pin = { x = 32.2, y = 27.7 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Speak with the Darkspear troll at Grom'gol who searches for a lost son of his tribe.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Nimboya is a troll of the {link:darkspear-trolls}Darkspear{/link} tribe, sent back to {link:stranglethorn-vale}Stranglethorn{/link} from far {link:orgrimmar}Orgrimmar{/link}. His task is grave. By an old custom of his people, the youngest son of his chief, {link:yenniku}Yenniku{/link}, was given to the Gurubashi trolls of {link:zul-gurub}Zul'Gurub{/link}. When the Darkspear left the jungle to follow {link:thrall}Thrall{/link}, the boy was left behind and lost. Nimboya has come to find him, alive or dead.]=],
		},
		{
			title = "Significance",
			text = [=[Nimboya speaks for the {link:darkspear-trolls}Darkspear{/link} in the land they once called home. Through him the tribe pursues its oldest feuds and its newest duties to the {link:horde}Horde{/link}: the search for {link:yenniku}Yenniku{/link}, the war on the Bloodscalps, the punishment of the {link:witherbark-trolls}Witherbark{/link} who betrayed the Warchief, and {link:vol-jin}Vol'jin{/link}'s plan to win the sword {link:trol-kalar}Trol'kalar{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• He hunted the Bloodscalp tribe for word of {link:yenniku}Yenniku{/link}.
• He inspected a great many shrunken heads, and gave thanks when the boy's was not among them.
• He forced the truth from the severed heads of the Bloodscalp chief and his witch doctor with a bubbling cauldron.
• He sent his pike north to the {link:the-hinterlands}Hinterlands{/link} as a grim message to the {link:witherbark-trolls}Witherbark trolls{/link}.
• He points the {link:horde}Horde{/link}'s champions toward {link:hammerfall}Hammerfall{/link} and the hunter {link:zengu}Zengu{/link}.]=],
		},
	},
	chapters = {
